  --stale-dash: 1.5 3.5;
  --halo-r-weak: 6px;
  --halo-o-weak: 0.10;
  --halo-r-medium: 11px;
  --halo-o-medium: 0.16;
  --halo-r-strong: 17px;
  --halo-o-strong: 0.22;

  /* Interior textures and the decision rail (A1, A2). These are unitless
     values on the shapes' 7-unit grid; viewer.js multiplies every texture,
     slot, and mark dimension by the current plate unit (--plate-r / 7). */
  --tx-hatch-pitch: 1.5556;
  --tx-hatch-weight: 0.5833;
  --tx-dot-r: 1.3222;
  --tx-keyline-inset: 1.5556;
  --rail-gap: 1.9444;
  --rail-w: 1.75;
  --rail-slot-h: 4.6667;
  --rail-slot-pitch: 5.0556;
  --rail-mark-0: 0.5833; /* a decided floor is a struck baseline, not silence (A2) */
  --rail-mark-1: 1.5556;
  --rail-mark-2: 3.1111;
  --rail-mark-3: 4.6667;
  --rail-mark-split: 1.3611; /* disputed is a fork, not a rung */
  --rail-radius: 0.4667;
  --zone-stroke: 1.6px;
  --chronic-stripe-pitch: 7px;
  --chronic-stripe-opacity: 0.30; /* on focus only (A6) */
  --hairline: 0.75px;
  --cartouche-pad: 4px; /* field-undefined frame â a dash on a boundary is freshness (A4) */
  --label-gap: 4px; /* clearance between a label and the last drawn mark on its side */
  /* label box estimate â the base glyph advance at --t-02 in --f-ui; the
     viewer widens it per glyph class (see LABEL_ADVANCE). Measured per string
     it would depend on the font the reader resolves, and the picture is
     seeded (Â§27.8) */
  --label-em: 5.8;
  --label-line: 13;
  --edge-lane: 7px; /* spacing between the strokes of one node pair */
  /* an edge leaving the focus horizon: how far it reaches past its own plate
     before it stops, and the angle its siblings fan across (radians) */
  --edge-stub: 14px;
  --edge-stub-fan: 1;
  /* presence a relation keeps while it is not the one picked: per family, so
     each lands *on* --rule's own contrast rather than a shared amount below
     its own. Measured over --page â the field's own surface, which is what a
     relation paints on; the plates are the --ground above it. Changing one
     means re-measuring it â the acceptance test does. */
  --recede-authored: 0.25;
  --recede-derived: 0.41;
  --recede-route: 0.57;

  /* Â§16.2 A11 density tiers, as multiples of --plate-r: a channel drops when
     the typical on-screen node spacing falls under tier Ã plate radius. The
     order is canon (rails+weight, labels, texture+boundary); the values are
     tokens. */
  --tier-decision-x: 4;
  --tier-label-x: 3;
  --tier-state-x: 2;

  /* motion â the question pull is a static kind mark; focus is the one
     transition, and never carries state (A9). */
  --m-pull-static-scale: 1.14;
  --m-focus: 120ms;
  --m-ease: cubic-bezier(0.4, 0, 0.2, 1);

  /* renderer-local surfaces, derived from the sheet above */
  --accent: var(--focus);
  --banner: var(--focus);
  --node-stroke: var(--ink);
  --shadow: oklch(0.245 0.008 250 / 0.12);

  font-family: var(--f-ui);
}

@media (prefers-color-scheme: dark) {
  :root {
    --page: oklch(0.185 0.008 250);
    --ground: oklch(0.225 0.009 250);
    --ground-sunk: oklch(0.265 0.01 250);
    --ink: oklch(0.935 0.005 250);
    --ink-2: oklch(0.735 0.01 250);
    --ink-3: oklch(0.555 0.012 250);
    --rule: oklch(0.325 0.012 250);
    --rule-soft: oklch(0.275 0.01 250);
    --focus: oklch(0.78 0.075 245);
    --select: oklch(0.86 0.06 245);
    --k-concept: oklch(0.74 0.075 252);
    --k-material: oklch(0.74 0.075 72);
    --k-part: oklch(0.74 0.075 96);
    --k-route: oklch(0.74 0.075 305);
    --k-direction: oklch(0.74 0.075 162);
    --k-question: oklch(0.74 0.075 46);
    --k-probe: oklch(0.74 0.075 225);
    --k-record: oklch(0.74 0.075 22);
    --k-plan: oklch(0.74 0.075 288);
    --k-pattern: oklch(0.74 0.075 140);
    --k-zone: oklch(0.74 0.075 196);
    --e-authored: oklch(0.70 0.014 250);
    --e-derived: oklch(0.50 0.014 250);
    --e-route: oklch(0.42 0.012 250);
    --trail: oklch(0.78 0.155 64);
    /* the same hairline floor, re-measured against this ground */
    --recede-authored: 0.21;
    --recede-derived: 0.36;
    --recede-route: 0.52;
    /* silence lightens against its ground rather than darkening, so an open
       slot stays a visible groove instead of a hole in the paper (A2) */
    --slot: oklch(0.395 0.013 250);
    --pull: oklch(0.79 0.105 52);
    --halo: oklch(0.75 0.05 250);
    --node-stroke: var(--ink);
    --shadow: oklch(0 0 0 / 0.3);
  }
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
}

body {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  color: var(--ink);
  background: var(--page);
}

button,
input {
  font: inherit;
}

button {
  color: var(--ink);
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  /* Wraps instead of clipping in narrow embeds (body overflow is hidden). */
  flex-wrap: wrap;
  gap: 6px 20px;
  min-height: 58px;
  padding: 6px 20px;
  border-bottom: 1px solid var(--rule);
  background: var(--ground);
}

.identity,
.view-controls,
.toggle-control {
  display: flex;
  align-items: center;
}

.view-controls {
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px 12px;
}

.identity {
  gap: 14px;
}

.wordmark {
  font-size: 1.12rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.field-chip,
.type-chip,
.badge {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 2px 9px;
  border: 1px solid var(--rule);
  border-radius: 999px;
  color: var(--ink-2);
  background: var(--ground-sunk);
  font-size: 0.78rem;
}

.toggle-control {
  gap: 7px;
  color: var(--ink-2);
  font-size: 0.88rem;
  cursor: pointer;
}

.toggle-control input {
  accent-color: var(--accent);
}

.toggle-control select {
  min-height: 32px;
  padding: 4px 8px;
  border: 1px solid var(--rule);
  border-radius: 6px;
  color: var(--ink-2);
  background: var(--ground);
  cursor: pointer;
}

.toggle-control select:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.toggle-control select:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.segmented-control {
  display: inline-flex;
}

.segmented-control button,
.legend-toggle {
  min-height: 32px;
  padding: 4px 10px;
  border: 1px solid var(--rule);
  color: var(--ink-2);
  background: var(--ground);
  cursor: pointer;
}

.segmented-control button:first-child {
  border-radius: 6px 0 0 6px;
}

.segmented-control button:last-child {
  margin-left: -1px;
  border-radius: 0 6px 6px 0;
}

.segmented-control button[aria-pressed="true"] {
  position: relative;
  color: var(--ink);
  background: var(--ground-sunk);
  box-shadow: inset 0 -2px 0 var(--accent);
}

.segmented-control button:disabled {
  color: var(--ink-2);
  cursor: not-allowed;
  opacity: 0.55;
}

.legend-toggle {
  border-radius: 6px;
}

.segmented-control button:focus-visible,
.legend-toggle:focus-visible,
.node-list-row:focus-visible {
  position: relative;
  z-index: 1;
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.legend {
  /* Anchored inside the app shell, so a wrapped (taller) header can never be
     covered â the shell starts wherever the header ends. */
  position: absolute;
  z-index: 12;
  top: 0;
  right: 20px;
  display: grid;
  grid-template-columns: repeat(2, minmax(180px, 1fr));
  gap: 24px;
  width: min(520px, calc(100vw - 40px));
  max-height: calc(100% - 18px);
  padding: 16px 18px;
  overflow: auto;
  border: 1px solid var(--rule);
  border-radius: 0 0 8px 8px;
  background: var(--ground);
  box-shadow: 0 8px 22px var(--shadow);
}

.legend[hidden] {
  display: none;
}

.legend:focus {
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}

.list-show-all {
  margin: 6px 0 0;
  padding: 7px 10px;
  border: 1px dashed var(--rule);
  border-radius: 5px;
  color: var(--accent);
  background: transparent;
  font-size: 0.84rem;
  cursor: pointer;
}

.list-show-all:hover {
  background: var(--ground);
}

.list-show-all:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.legend h2 {
  margin: 0 0 9px;
  font-size: 0.82rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.legend-row {
  display: flex;
  min-height: 24px;
  align-items: center;
  gap: 9px;
  color: var(--ink-2);
  font-size: 0.8rem;
}

.node-glyph {
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  overflow: visible;
}

.legend-edge-sample {
  width: 34px;
  height: 12px;
  flex: 0 0 34px;
  overflow: visible;
}

.node-glyph .question-ring {
  animation: none;
  opacity: 1;
  transform: scale(1);
}

.legend-direction {
  margin: 9px 0 0;
  color: var(--ink-2);
  font-size: 0.76rem;
  line-height: 1.35;
}

.app-shell {
  position: relative;
  display: grid;
  min-width: 0;
  min-height: 0;
  grid-template-columns: minmax(0, 1fr);
}

.app-shell.details-open {
  grid-template-columns: minmax(0, 1fr) 320px;
}

main {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

aside {
  position: relative;
  width: 320px;
  min-height: 0;
  padding: 24px 20px 36px;
  overflow: auto;
  border-left: 1px solid var(--rule);
  background: var(--ground);
  box-shadow: -8px 0 20px var(--shadow);
}

.close-details {
  position: absolute;
  top: 10px;
  right: 12px;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  font-size: 1.4rem;
  line-height: 1;
  cursor: pointer;
}

.close-details:hover,
.close-details:focus-visible {
  background: var(--ground-sunk);
  outline: 2px solid var(--focus);
  outline-offset: 1px;
}

.status-bar {
  display: flex;
  align-items: center;
  min-width: 0;
  min-height: 30px;
  padding: 0 18px;
  overflow: hidden;
  border-top: 1px solid var(--rule);
  color: var(--ink-2);
  background: var(--ground);
  font-size: 0.76rem;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.state-block,
.layout-message {
