}

.state-block a {
  color: var(--accent);
  text-underline-offset: 3px;
}

.banner {
  position: absolute;
  z-index: 4;
  top: 14px;
  left: 18px;
  right: 18px;
  min-height: 36px;
  padding: 8px 12px;
  border: 1px solid var(--rule);
  border-left: 4px solid var(--banner);
  border-radius: 3px;
  color: var(--ink);
  background: var(--ground);
  box-shadow: 0 3px 12px var(--shadow);
  font-size: 0.86rem;
  line-height: 1.35;
}

.node-list {
  width: 100%;
  height: 100%;
  padding: 18px clamp(16px, 4vw, 52px) 36px;
