  border-radius: 6px;
  color: var(--ink);
  background: var(--ground);
  box-shadow: 0 2px 8px var(--shadow);
  cursor: pointer;
}

.zoom-controls button:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

/* the stroke scales with the picture like every other mark, so a zoomed-out
   field does not bury its plates under the relation mesh â down to a floor of
   screen presence, on the same --dash-scale the dash and the hit band ride.
   Under that floor a relation is not omitted in A11's fixed order, it is gone,
   and A11 has no fading step. The lift multiplies each family's own width, so
   the ratios that carry family (A3) survive it. Declared here rather than on
   :root: a custom property's var()s resolve on the element that declares it,
   and :root would capture the fallback --dash-scale of 1. */
.edge-line {
  fill: none;
  stroke: var(--e-authored);
  stroke-linecap: round;
  --edge-floor: max(1, var(--edge-hairline, 0.58) / var(--screen-scale, 1));
  stroke-width: calc(1px * var(--edge-floor));
}

.edge-route {
  stroke: var(--e-route);
  stroke-width: calc(1px * var(--edge-floor));
  stroke-dasharray: calc(4 * var(--dash-scale)) calc(3 * var(--dash-scale));
}

.edge-trail {
  stroke: var(--trail);
  stroke-width: calc(2.5px * var(--edge-floor));
}

.edge-authored {
  stroke-width: calc(var(--w-stroke) * var(--edge-floor));
}

.edge-structural {
  stroke: var(--e-derived);
  stroke-width: calc(1px * var(--edge-floor));
  stroke-dasharray: calc(1 * var(--dash-scale)) calc(3 * var(--dash-scale));
}

.edge-journal {
  stroke: var(--e-derived);
  stroke-width: calc(1.25px * var(--edge-floor));
  stroke-dasharray:
    calc(6 * var(--dash-scale)) calc(2 * var(--dash-scale))
    calc(1 * var(--dash-scale)) calc(2 * var(--dash-scale));
}

/* Â§16.2 A3: an asserted weight is a mark in the margin of the stroke, so the
   stroke keeps carrying family alone and unassessed can read as a hole. */
.edge-weight {
  fill: none;
  stroke: var(--struck);
  stroke-width: var(--w-stroke);
  stroke-linecap: butt;
  vector-effect: non-scaling-stroke;
}

/* #99: a round cap reads as an endpoint, which is the one thing a stub must
   not say, so the cut end is squared off and left bare */
.edge-stub {
  stroke-linecap: butt;
}

/* and while the floor is lifting the stroke, so is every relation: a round cap
   would run half its lifted width back over the plate the trim cleared */
.viewport.floored .edge-line {
  stroke-linecap: butt;
}

.edge-hit {
  fill: none;
  stroke: transparent;
  /* Twelve CSS pixels wherever the picture is smaller than itself, camera or
     frame: a field fitted by zoom, or a narrow embed, would otherwise leave a
     hit band under a pixel wide. Written into the width rather than as
     non-scaling-stroke, which Chromium honours when painting but not when
     hit-testing. Above its own scale the band grows with the stroke. */
  stroke-width: calc(12px * max(1, 1 / var(--screen-scale, 1)));
  pointer-events: stroke;
}

.edge-group:hover .edge-line {
  filter: drop-shadow(0 0 2px var(--focus));
}

/* Â§16.2 A9 focus feedback (Â§16.3). On the leaf marks, never on the group: a
   group below full opacity is its own transparency layer and measured four
   times the cost of a pan. opacity rather than stroke-opacity because an
   arrowhead is a marker filled with context-stroke, which copies the paint
   but not the stroke's own opacity. A9 gives focus feedback the one transition
   there is, and reduced motion collapses it to zero below. The trail is
   exempt (A7).
   Each amount is divided by how much of its own mark is actually painted. A
   stroke narrower than a pixel does not paint a thin line, it paints a pale
   one â the width is the coverage â so a family already spending part of its
   presence on being drawn at all has that much less to spend on being quiet,
   and the amount measured at full width would land it under the floor.
   --edge-cover is that fraction: the family's own width in units, at the size
   the picture is drawn (never under the lift's floor), capped at the pixel
   where coverage is whole. At full size it is 1 and the division is the
   identity. Compensating in the width instead is not open: the lift would have
   to differ per family and width carries family alone (A3). Where even the
   whole amount cannot be spent the quiet stands down at 1, which is the answer
   forced colours already get; the selection still answers through the ring and
   through the panel's words (A8). */
.viewport.has-selection .edge-group:not(.incident) {
  --edge-units: 1;
  --edge-cover: min(1, calc(
    var(--edge-units) * max(var(--screen-scale, 1), var(--edge-hairline))));
  --edge-recede: min(1, calc(var(--recede-derived) / var(--edge-cover)));
}

.viewport.has-selection .edge-group:not(.incident)[data-family="journal"] {
  --edge-units: 1.25;
}

.viewport.has-selection .edge-group:not(.incident)[data-family="authored"] {
  --edge-units: 1.5; /* --w-stroke, as a number */
  --edge-recede: min(1, calc(var(--recede-authored) / var(--edge-cover)));
}

.viewport.has-selection .edge-group:not(.incident)[data-family="route"] {
  --edge-recede: min(1, calc(var(--recede-route) / var(--edge-cover)));
}

.viewport.has-selection .edge-group:not(.incident)[data-family="trail"] {
  --edge-recede: 1;
}

.edge-line,
.edge-weight {
  transition: opacity var(--focus-settle) ease;
}

.viewport.has-selection .edge-group:not(.incident) .edge-line,
.viewport.has-selection .edge-group:not(.incident) .edge-weight {
  opacity: var(--edge-recede);
}

/* quiet, never gone â a receded relation still answers the hand */
.viewport.has-selection .edge-group:not(.incident):hover .edge-line,
.viewport.has-selection .edge-group:not(.incident):hover .edge-weight {
  opacity: 1;
}

.edge-label {
  display: none;
  fill: var(--ink);
  stroke: var(--ground);
  stroke-width: 3px;
  paint-order: stroke;
  font-size: var(--t-01);
  pointer-events: none;
}

.edge-label.visible {
  display: block;
}

.node {
  cursor: pointer;
}

/* One hue per kind (A7), carried by a custom property so the plate fill,
   the touched dot, and the legend samples all read the same token. */
.node-concept { --plate-hue: var(--k-concept); }
.node-material { --plate-hue: var(--k-material); }
.node-material_part { --plate-hue: var(--k-part); }
.node-suggested_route { --plate-hue: var(--k-route); }
.node-direction { --plate-hue: var(--k-direction); }
.node-question { --plate-hue: var(--k-question); }
.node-probe { --plate-hue: var(--k-probe); }
.node-artifact,
.node-encounter,
.node-trail_segment,
.node-personal_trail { --plate-hue: var(--k-record); }
.node-plan { --plate-hue: var(--k-plan); }
.node-pattern { --plate-hue: var(--k-pattern); }
.node-zone { --plate-hue: var(--k-zone); }

/* the outline holds 1.5px however far the view zooms out, so a whole field
   never reads as a mesh with its nodes lost in it */
.node-shape {
  fill: var(--plate-hue, var(--k-concept));
  stroke: var(--node-stroke);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

/* Â§16.2 A1: interior texture is the monotone contact ladder. The two open
   rungs empty the plate; hatch and cross-hatch reference the per-kind
   patterns from the defs (SVG pattern content cannot inherit the referencing
   element's colour, hence tx-{texture}-{kind} ids); solid is the kind hue;
   taught adds the inner keyline element. */
.tx-plain .node-shape,
.tx-dot .node-shape {
  fill: var(--ground);
}

.node-concept.tx-hatch .node-shape { fill: url(#tx-hatch-concept); }
.node-concept.tx-cross .node-shape { fill: url(#tx-cross-concept); }
.node-material.tx-hatch .node-shape { fill: url(#tx-hatch-material); }
.node-material.tx-cross .node-shape { fill: url(#tx-cross-material); }
.node-material_part.tx-hatch .node-shape { fill: url(#tx-hatch-material_part); }
.node-material_part.tx-cross .node-shape { fill: url(#tx-cross-material_part); }

.tx-ground {
  fill: var(--ground);
}

.tx-ink-concept { stroke: var(--k-concept); }
.tx-ink-material { stroke: var(--k-material); }
.tx-ink-material_part { stroke: var(--k-part); }

.plate-dot {
  fill: var(--plate-hue, var(--k-concept));
}

.plate-keyline {
  fill: none;
  stroke: var(--ground);
  stroke-width: var(--w-stroke);
}

/* Â§16.2 A4: the three freshness classes are three boundary continuities; a
   dash on a node boundary is always freshness. No freshness class (no
   contact) keeps the same solid boundary as fresh â the empty plate already
   says no contact, and the panel and list say it in words (A8). */
.fresh-fresh .node-shape { stroke-dasharray: var(--fresh-dash); }
.fresh-aging .node-shape { stroke-dasharray: var(--aging-dash); }
.fresh-stale .node-shape { stroke-dasharray: var(--stale-dash); }

/* A6: stale recedes â the label mutes, nothing enlarges or alarms. */
.fresh-stale .node-label {
  fill: var(--ink-3);
}

/* Â§16.2 A2: the decision rail. An open slot is drawn (silence is visible), a
   struck mark's extent carries the decided level, the fork carries disputed. */
.rail-slot {
  fill: var(--slot);
}

.rail-mark {
  fill: var(--struck);
}

/* The field-undefined flag left the node boundary for this hairline frame â
   A4 reserves boundary dashes for freshness. The flag is also a word in the
   panel and the list, so the reading never depends on the frame. */
.cartouche {
  fill: none;
  stroke: var(--rule);
  stroke-width: var(--hairline);
  vector-effect: non-scaling-stroke;
}

.selection-ring,
.focus-ring {
  fill: none;
  stroke: var(--focus);
  stroke-width: 3;
  vector-effect: non-scaling-stroke;
}

/* drawn on every plate and shown by state, so a change of selection is a
   class on a tree that is already right */
.selection-ring {
  opacity: 0;
  pointer-events: none;
}

.node.selected .selection-ring {
  opacity: 1;
}

.focus-ring {
  opacity: 0;
  stroke-dasharray: 3 3;
  pointer-events: none;
}

.node:focus-visible .focus-ring {
  opacity: 1;
}

.sensitivity-dot {
  fill: var(--ink);
  stroke: var(--ground);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.question-ring {
  fill: none;
  stroke: var(--k-question);
  stroke-width: 1.5;
  transform-box: fill-box;
  transform-origin: center;
  opacity: 1;
  transform: scale(var(--m-pull-static-scale));
  vector-effect: non-scaling-stroke;
}

.node-label {
  fill: var(--ink);
  stroke: var(--page);
  stroke-width: 3px;
  paint-order: stroke;
  font-size: var(--t-02);
  pointer-events: none;
}

.weight-dropped {
  display: none;
}

/* Â§16.2 A11: as density rises the channels drop whole and in the canon's
   fixed order â decision rails and weight marks together, then labels, then
   interior texture and boundary continuity â never a cluster, average,
   count, or heat in their place. */
.viewport.drop-decision .weight-detail,
.viewport.drop-decision .edge-weight,
.viewport.drop-decision .rail {
  display: none;
}

.viewport.drop-decision .weight-dropped {
  display: inline;
}

/* Labels drop whole â selection included: the status line says the channel
   is not drawn, and the panel and list carry the name (A8, A11). */
.viewport.drop-labels .node-label,
.viewport.drop-labels .edge-label {
  display: none;
}

/* The last tier: a node drawn without a boundary is drawn without state â
   the plate falls back to its plain kind reading, and the status line names
   what is not drawn. */
.viewport.drop-state .node-shape {
  fill: var(--plate-hue, var(--k-concept));
  stroke-dasharray: none;
}

.viewport.drop-state .plate-dot,
.viewport.drop-state .plate-keyline {
  display: none;
}

.viewport.drop-state .fresh-stale .node-label {
  fill: var(--ink);
}

#detail-content h2 {
  margin: 8px 38px 10px 0;
  font-size: 1.2rem;
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.detail-meta,
.detail-flags {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  margin: 8px 0;
}

.detail-id {
  margin: 10px 0;
  color: var(--ink-2);
  font-family: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", monospace;
  font-size: 0.78rem;
  overflow-wrap: anywhere;
}

.detail-fields,
.detail-formerly {
  margin: 7px 0;
  color: var(--ink-2);
  font-size: 0.84rem;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.detail-rows {
  display: grid;
  gap: 10px;
  margin: 18px 0 22px;
}

.detail-row {
  display: grid;
  gap: 3px;
}

.detail-row dt,
.edge-groups h3,
.state-groups h3 {
  color: var(--ink-2);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.detail-row dd {
  margin: 0;
  font-size: 0.87rem;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.detail-row a {
  color: var(--accent);
}

.detail-long {
  margin: 0;
  white-space: pre-wrap;
}

.edge-groups {
  display: grid;
  gap: 14px;
}

.edge-group-list {
  display: grid;
  gap: 6px;
}

.edge-group-list button {
  padding: 3px 0;
  border: 0;
  color: var(--accent);
  background: transparent;
  text-align: left;
  overflow-wrap: anywhere;
  cursor: pointer;
}

.edge-meta {
  color: var(--ink-2);
  font-size: 0.76rem;
}

@media (max-width: 720px) {
  .site-header {
    padding: 0 10px;
  }

  .identity {
    gap: 7px;
  }

  .view-controls {
    gap: 6px;
  }

  .legend {
    right: 10px;
    grid-template-columns: 1fr;
    width: min(360px, calc(100vw - 20px));
  }

  .node-list-row,
  .node-list-section[data-node-type] .node-list-row {
    grid-template-columns: 18px minmax(0, 1fr);
  }

  .node-list-id,
  .node-list-state,
  .node-list-row .badge {
    grid-column: 2;
  }

  .edge-list-row {
    grid-template-columns: minmax(0, 1fr);
  }

  .app-shell.details-open {
    grid-template-columns: minmax(0, 1fr);
  }

  aside {
    /* Absolute against the app shell, so the drawer starts below the header
       and above the status bar whatever their wrapped heights are. */
    position: absolute;
    z-index: 8;
    top: 0;
    right: 0;
    bottom: 0;
    width: min(320px, 90vw);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    scroll-behavior: auto;
    transition-duration: 0s;
  }

  /* A9's transitions collapse to zero. Through the token, not the rule above:
     that one is a universal selector and loses to any class that names its own
     duration â the quiet then arrives already arrived. */
  :root {
    --focus-settle: 0s;
  }
}

/* Â§27.8: every state distinction is structural â texture, boundary
   continuity, mark presence, mark extent â so under forced colours the
   system palette replaces the tokens and the structure keeps carrying the
   reading. Hue stops naming kinds (shape still does, A8); the trail keeps
   the one emphasis role via Highlight (A7). */
@media (forced-colors: active) {
  :root {
    --page: Canvas;
    --ground: Canvas;
    --ground-sunk: Canvas;
    --ink: CanvasText;
    --ink-2: CanvasText;
    --ink-3: GrayText;
    --rule: CanvasText;
    --rule-soft: GrayText;
    --focus: Highlight;
    --select: Highlight;
    --k-concept: CanvasText;
    --k-material: CanvasText;
    --k-part: CanvasText;
    --k-route: CanvasText;
    --k-direction: CanvasText;
    --k-question: CanvasText;
    --k-probe: CanvasText;
    --k-record: CanvasText;
    --k-plan: CanvasText;
    --k-pattern: CanvasText;
    --k-zone: CanvasText;
    --e-authored: CanvasText;
    --e-derived: CanvasText;
    --e-route: GrayText;
    --trail: Highlight;
    --slot: GrayText;
    --struck: CanvasText;
    --pull: CanvasText;
    --halo: CanvasText;
    --node-stroke: CanvasText;
    --shadow: transparent;
    /* no rank below CanvasText, so nothing to recede to that clears --rule:
       the emphasis stands down and the ring and panel answer instead (A8) */
    --recede-authored: 1;
    --recede-derived: 1;
    --recede-route: 1;
  }

  .graph-svg,
  .node-glyph,
  .legend-edge-sample,
  .legend-state-sample {
    forced-color-adjust: none;
  }
}
